import {SCENARIOS} from './engine.js';
import {truthStoryPacket} from './truth-story-model.js';
import {nextAngleModel} from './next-angle-core.js';
import {matchSession} from './match-session.js';

const words={
 en:{button:'Request the next angle ↗',eyebrow:'BTR / NEXT ANGLE',heading:'One missing view can change the call.',lead:'Check asks for the exact observation needed before the studio commits to a story.',ask:'CHECK → PRODUCTION',request:'Did Laurent shift with Moreau’s run, or hold his position?',window:'SYNTHETIC TRACKING WINDOW',initial:'Ask for the alternate view',received:'Load the authored alternate',unavailable:'No usable view',reset:'Reset the request',original:'ORIGINAL RECORD · R1',alternate:'ALTERNATE RECORD · R2',waiting:'Awaiting the requested view',missing:'No new observation arrived. Keep the movement observation, withhold any causal claim.',changed:'The alternate holds Laurent still. Withdraw the movement claim; keep the completed passes.',metric:'LATERAL SHIFT',pass:'PASSES TO A TEAMMATE',passCount:(n,d)=>n+' of '+d+' completed at this cutoff',claim:'CHECKED CLAIMS CHANGED',forecast:'If the alternate shows Laurent stationary',forecastCopy:'Withdraw the movement sentence. The completed passes survive. Do not claim what caused the run.',broadcast:'BROADCAST LINE',export:'Download production cue JSON',watch:'Watch the revised play ↗',close:'Close Next Angle',scope:'Authored synthetic alternative · deterministic comparison · no new Azure model request. This is not an independent camera feed or proof of causation.',diagram:'Diagram of two synthetic tracking interpretations. Not measured video.'},
 es:{button:'Pedir otro ángulo ↗',eyebrow:'BTR / OTRO ÁNGULO',heading:'Una vista puede cambiar el relato.',lead:'Check pide la observación exacta antes de publicar una explicación.',ask:'CHECK → PRODUCCIÓN',request:'¿Laurent siguió la carrera de Moreau o mantuvo su posición?',window:'VENTANA SINTÉTICA',initial:'Pedir la vista alternativa',received:'Cargar la alternativa creada',unavailable:'No hay vista útil',reset:'Reiniciar solicitud',original:'REGISTRO ORIGINAL · R1',alternate:'REGISTRO ALTERNATIVO · R2',waiting:'Esperando la vista solicitada',missing:'No llegó una observación nueva. Mantener el movimiento observado y evitar afirmar una causa.',changed:'La alternativa mantiene a Laurent quieto. Retirar la afirmación del movimiento; conservar los pases.',metric:'DESPLAZAMIENTO LATERAL',pass:'PASES A UN COMPAÑERO',passCount:(n,d)=>n+' de '+d+' completados hasta este momento',claim:'AFIRMACIONES MODIFICADAS',forecast:'Si Laurent permanece quieto',forecastCopy:'Retirar la frase del movimiento. Los pases completados siguen. No afirmar la causa.',broadcast:'LÍNEA DE EMISIÓN',export:'Descargar JSON de producción',watch:'Ver la jugada revisada ↗',close:'Cerrar',scope:'Alternativa sintética creada · comparación determinista · sin nueva petición al modelo Azure. No es otra cámara independiente ni prueba causal.',diagram:'Diagrama de dos interpretaciones sintéticas. No es vídeo medido.'},
 pt:{button:'Pedir outro ângulo ↗',eyebrow:'BTR / OUTRO ÂNGULO',heading:'Uma vista pode mudar a história.',lead:'Check pede a observação necessária antes da publicação.',ask:'CHECK → PRODUÇÃO',request:'Laurent seguiu Moreau ou ficou na posição inicial?',window:'JANELA SINTÉTICA',initial:'Pedir vista alternativa',received:'Carregar alternativa criada',unavailable:'Sem vista útil',reset:'Reiniciar pedido',original:'REGISTRO ORIGINAL · R1',alternate:'REGISTRO ALTERNATIVO · R2',waiting:'Aguardando a vista pedida',missing:'Nenhuma nova observação chegou. Manter apenas o movimento observado, sem afirmar causa.',changed:'A alternativa mantém Laurent parado. Retirar a afirmação de movimento; manter os passes.',metric:'DESLOCAMENTO LATERAL',pass:'PASSES A UM COLEGA',passCount:(n,d)=>n+' de '+d+' concluídos até este momento',claim:'AFIRMAÇÕES ALTERADAS',forecast:'Se Laurent ficar parado',forecastCopy:'Retirar a frase de movimento. Os passes permanecem. Não afirmar causalidade.',broadcast:'LINHA DE TRANSMISSÃO',export:'Baixar JSON de produção',watch:'Ver jogada revisada ↗',close:'Fechar',scope:'Alternativa sintética criada · comparação determinística · sem nova chamada ao modelo Azure. Não é outra câmera independente nem prova causal.',diagram:'Diagrama de duas interpretações sintéticas. Não é vídeo medido.'}
};
const el=(tag,cls,text)=>{const node=document.createElement(tag);node.className=cls;if(text)node.textContent=text;return node;};
export function createNextAngle({toggleCorrection,pause,seek}){
 const button=el('button','outline-button next-angle-launch');button.type='button';button.hidden=true;
 const dialog=el('dialog','next-angle-dialog');dialog.setAttribute('aria-labelledby','next-angle-title');
 dialog.innerHTML=`<div class="next-angle-shell"><header class="next-angle-top"><div><p class="next-angle-kicker"></p><h2 id="next-angle-title"></h2><p class="next-angle-lead"></p></div><button class="next-angle-close" type="button" aria-label="Close">×</button></header><div class="next-angle-columns"><section class="next-angle-stage"><div class="next-angle-ask"><span></span><strong></strong><small></small></div><div class="next-angle-pitch" role="img"><div class="next-angle-line"></div><div class="next-angle-run"><i></i><b>MOREAU</b></div><div class="next-angle-defender"><i></i><b>LAURENT / R1</b></div><div class="next-angle-still"><i></i><b>LAURENT / R2</b></div><div class="next-angle-ball"></div></div><p class="next-angle-diagram"></p><div class="next-angle-controls"><button type="button" class="next-angle-request"></button><button type="button" class="next-angle-receive"></button><button type="button" class="next-angle-unavailable"></button><button type="button" class="next-angle-reset"></button></div></section><section class="next-angle-results"><div class="next-angle-status" role="status"></div><div class="next-angle-readouts"><div><small class="next-angle-metric-label"></small><strong class="next-angle-shift"></strong><span class="next-angle-shift-caption"></span></div><div><small class="next-angle-pass-label"></small><strong class="next-angle-pass"></strong><span class="next-angle-pass-caption"></span></div><div><small class="next-angle-claim-label"></small><strong class="next-angle-claim"></strong><span class="next-angle-claim-caption"></span></div></div><div class="next-angle-forecast"><small>CHECK / CONDITIONAL CALL</small><h3></h3><p></p></div><div class="next-angle-lines"><div><small class="next-angle-original-label"></small><p class="next-angle-original-line"></p></div><div><small class="next-angle-alternate-label"></small><p class="next-angle-alternate-line"></p></div></div><div class="next-angle-actions"><button type="button" class="next-angle-export"></button><button type="button" class="next-angle-watch"></button></div></section></div><footer class="next-angle-scope"></footer></div>`;
 document.body.append(dialog);
 const q=selector=>dialog.querySelector(selector);const original=SCENARIOS.find(s=>s.id==='wide');
 let model=null,state='idle',lastPacket=null;
 const set=(selector,value)=>{q(selector).textContent=value;};
 const open=()=>{pause();if(lastPacket?.sequence_second<16)seek(16,false);if(!dialog.open)dialog.showModal();render(lastPacket);};
 button.onclick=open;q('.next-angle-close').onclick=()=>dialog.close();
 dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();});
 q('.next-angle-request').onclick=()=>{state='requested';render(lastPacket);};
 q('.next-angle-receive').onclick=()=>{if(!matchSession.get().corrected)toggleCorrection();state='received';render(lastPacket);};
 q('.next-angle-unavailable').onclick=()=>{state='unavailable';render(lastPacket);};
 q('.next-angle-reset').onclick=()=>{if(matchSession.get().corrected)toggleCorrection();state='idle';render(lastPacket);};
 q('.next-angle-watch').onclick=()=>{dialog.close();document.getElementById('watch-nav')?.click();};
 q('.next-angle-export').onclick=()=>{if(!model)return;const payload={...model,delivery:{state,generated_at:new Date().toISOString(),model_requests:0,disclaimer:'Deterministic cue from authored synthetic evidence; no independent video observation.'}};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`btr-next-angle-${model.clock.replace(':','-')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 function render(packet){
  if(packet)lastPacket=packet;
  const active=lastPacket?.scenario==='wide'&&lastPacket.sequence_second>=16;
  button.hidden=lastPacket?.scenario!=='wide';const c=words[matchSession.get().language]||words.en;button.textContent=c.button;
  if(!active||!dialog.open)return;
  const source=truthStoryPacket(original,lastPacket.sequence_second,false,'fan',matchSession.get().language);
  const alternate=truthStoryPacket(original,lastPacket.sequence_second,true,'fan',matchSession.get().language);
  model=nextAngleModel(source,alternate);
  if(lastPacket.revision===2)state='received';
  dialog.dataset.state=state;
  set('.next-angle-kicker',c.eyebrow);set('#next-angle-title',c.heading);set('.next-angle-lead',c.lead);q('.next-angle-close').setAttribute('aria-label',c.close);
  set('.next-angle-ask span',c.ask);set('.next-angle-ask strong',c.request);set('.next-angle-ask small',`${c.window} ${model.request.window} · ${model.source.original}`);
  set('.next-angle-diagram',c.diagram);q('.next-angle-pitch').setAttribute('aria-label',c.diagram);
  set('.next-angle-request',c.initial);set('.next-angle-receive',c.received);set('.next-angle-unavailable',c.unavailable);set('.next-angle-reset',c.reset);
  q('.next-angle-request').hidden=state!=='idle';q('.next-angle-receive').hidden=state!=='requested';q('.next-angle-unavailable').hidden=state!=='requested';q('.next-angle-reset').hidden=state==='idle';
  set('.next-angle-status',state==='received'?c.changed:state==='unavailable'?c.missing:c.waiting);
  set('.next-angle-metric-label',c.metric);set('.next-angle-shift',`${model.measured.original_movement_m.toFixed(1)} → ${state==='received'?model.measured.alternate_movement_m.toFixed(1):'?'} m`);set('.next-angle-shift-caption',`${model.source.original} → ${state==='received'?model.source.alternate:'view pending'}`);
  set('.next-angle-pass-label',c.pass);set('.next-angle-pass',`${model.measured.pass_completions}/${model.measured.pass_attempts} · ${model.measured.pass_completion_percent}%`);set('.next-angle-pass-caption',c.passCount(model.measured.pass_completions,model.measured.pass_attempts));
  set('.next-angle-claim-label',c.claim);set('.next-angle-claim',state==='received'?`${model.measured.claims_changed}/${model.measured.claims_checked}`:`0/${model.measured.claims_checked}`);set('.next-angle-claim-caption',state==='received'?'Movement withdrawn; other checks preserved':'Conditional until alternate is received');
  set('.next-angle-forecast h3',c.forecast);set('.next-angle-forecast p',c.forecastCopy);
  set('.next-angle-original-label',c.original);set('.next-angle-original-line',source.narrative.currentLine);set('.next-angle-alternate-label',state==='received'?c.alternate:c.broadcast);set('.next-angle-alternate-line',state==='received'?alternate.narrative.currentLine:state==='unavailable'?c.missing:c.waiting);
  set('.next-angle-export',c.export);set('.next-angle-watch',c.watch);q('.next-angle-watch').hidden=state!=='received';set('.next-angle-scope',c.scope);
 }
 return {button,render};
}
